// VARIANT input/output syntax and __VARINFO generic typing
VAR_IN_OUT
    item : VARIANT;
END_VAR
VAR
    info : __SYSTEM.VAR_INFO;
END_VAR
info := __VARINFO(item);
IF info.TypeClass = __SYSTEM.TYPE_CLASS.TYPE_INT THEN
    // Inspect or process dynamically typed variable
END_IF;

// VAR_IN_OUT structures and arrays modify caller storage directly
VAR_IN_OUT
    recipe : ST_Recipe;
    records : ARRAY[1..10] OF INT;
END_VAR
recipe.status := 1;
records[1] := records[1] + 1;
// Note: VAR_IN_OUT parameters cannot specify default initializers

// R_TRIG / F_TRIG function blocks and manual edge detection pattern
VAR
    rTrig : R_TRIG;
    prevSignal : BOOL;
    rising : BOOL;
END_VAR
rTrig(CLK := rawSignal); // rTrig.Q is TRUE for one scan on rising edge
// Manual edge pattern:
rising := rawSignal AND NOT prevSignal;
prevSignal := rawSignal;

// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!
VAR
    timer : TON;
    runTimer : BOOL;
END_VAR
// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):
runTimer := (state = 1) AND NOT resetCmd;
timer(IN := runTimer, PT := T#2s);
IF timer.Q THEN
    // Timer expired; timer.ET holds elapsed time
END_IF;
